class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0, which is (0, 0)
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Calculate final position: row * n + col
        return row * n + col

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Count the frequency of each color for each player
        player_color_count = {}

        for player, color in pick:
            if player not in player_color_count:
                player_color_count[player] = {}
            player_color_count[player][color] = player_color_count[player].get(color, 0) + 1

        # Count winning players
        winners = 0

        for player in range(n):
            if player not in player_color_count:
                continue

            # Check if player has at least (player + 1) balls of the same color
            max_count = max(player_color_count[player].values())
            if max_count >= player + 1:
                winners += 1

        return winners

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Calculate flips needed for all rows
        row_flips = 0
        for i in range(m):
            for j in range(n // 2):
                # Compare j-th and (n-1-j)-th positions in row i
                if grid[i][j] != grid[i][n - 1 - j]:
                    row_flips += 1

        # Calculate flips needed for all columns
        col_flips = 0
        for j in range(n):
            for i in range(m // 2):
                # Compare i-th and (m-1-i)-th positions in column j
                if grid[i][j] != grid[m - 1 - i][j]:
                    col_flips += 1

        # Return minimum of row flips and column flips
        return min(row_flips, col_flips)

from itertools import combinations, permutations

N, K = map(int, input().split())
functions = []
for _ in range(N):
    A, B = map(int, input().split())
    functions.append((A, B))

if K == 1:
    result = max(A * 1 + B for A, B in functions)
else:
    result = 0
    # Try all combinations of K distinct functions
    for selected_indices in combinations(range(N), K):
        # Try all permutations of selected indices
        for perm in permutations(selected_indices):
            current_value = 1
            for i in perm:
                A, B = functions[i]
                current_value = A * current_value + B
            result = max(result, current_value)

print(result)

