N, M = map(int, input().split())

# If no edges, any value works
if M == 0:
    print("Yes")
    print("1 " * N)
else:
    # Build adjacency list and compute degrees
    degree = [0] * (N + 1)

    for _ in range(M):
        u, v = map(int, input().split())
        degree[u] += 1
        degree[v] += 1

    # Check if any vertex has degree 1
    has_degree_1 = False
    for i in range(1, N + 1):
        if degree[i] == 1:
            has_degree_1 = True
            break

    if has_degree_1:
        print("No")
    else:
        print("Yes")
        print(" ".join(["1"] * N))

